public class InnerConnectorAzureScopeConfigurationMapFactory(Action<Humidifier.InspectorV2.ConnectorTypes.AzureScopeConfigurationMap> factoryAction = null) : SubResourceFactory<Humidifier.InspectorV2.ConnectorTypes.AzureScopeConfigurationMap>
{

    internal InnerConnectorScopeConfigurationFactory ServerlessScanningFactory { get; set; }

    internal InnerConnectorScopeConfigurationFactory ContainerImageScanningFactory { get; set; }

    internal InnerConnectorScopeConfigurationFactory VmScanningFactory { get; set; }

    protected override Humidifier.InspectorV2.ConnectorTypes.AzureScopeConfigurationMap Create()
    {
        var azureScopeConfigurationMapResult = CreateAzureScopeConfigurationMap();
        factoryAction?.Invoke(azureScopeConfigurationMapResult);

        return azureScopeConfigurationMapResult;
    }

    private Humidifier.InspectorV2.ConnectorTypes.AzureScopeConfigurationMap CreateAzureScopeConfigurationMap()
    {
        var azureScopeConfigurationMapResult = new Humidifier.InspectorV2.ConnectorTypes.AzureScopeConfigurationMap();

        return azureScopeConfigurationMapResult;
    }
    public override void CreateChildren(Humidifier.InspectorV2.ConnectorTypes.AzureScopeConfigurationMap result)
    {
        base.CreateChildren(result);

        result.ServerlessScanning ??= ServerlessScanningFactory?.Build();
        result.ContainerImageScanning ??= ContainerImageScanningFactory?.Build();
        result.VmScanning ??= VmScanningFactory?.Build();
    }

} // End Of Class

